command:
set -eu
mv /etc/fleet-https/node2.key /etc/pki/tls/private/fleet-node2.key
mv /etc/fleet-https/node2.crt /etc/pki/tls/certs/fleet-node2.crt
rmdir /etc/fleet-https
chmod 0600 /etc/pki/tls/private/fleet-node2.key
chmod 0644 /etc/pki/tls/certs/fleet-node2.crt
restorecon -v /etc/pki/tls/private/fleet-node2.key /etc/pki/tls/certs/fleet-node2.crt
cp -a /etc/nginx/nginx.conf /etc/nginx/nginx.conf.vendor
cat > /etc/nginx/nginx.conf <<'FLEET_NGINX_MAIN'
user nginx;
worker_processes auto;
error_log /var/log/nginx/error.log notice;
pid /run/nginx.pid;

events {
    worker_connections 1024;
}

http {
    include /etc/nginx/mime.types;
    default_type application/octet-stream;
    log_format main '$remote_addr - $remote_user [$time_local] "$request" '
                    '$status $body_bytes_sent "$http_referer" '
                    '"$http_user_agent" "$http_x_forwarded_for"';
    access_log /var/log/nginx/access.log main;
    sendfile on;
    keepalive_timeout 65;
    include /etc/nginx/conf.d/*.conf;
}
FLEET_NGINX_MAIN
cat > /etc/nginx/conf.d/fleet-https.conf <<'FLEET_NGINX_SITE'
server {
    listen 8443 ssl;
    listen [::]:8443 ssl;
    server_name node2;

    ssl_certificate /etc/pki/tls/certs/fleet-node2.crt;
    ssl_certificate_key /etc/pki/tls/private/fleet-node2.key;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_cache shared:FLEETSSL:10m;
    ssl_session_timeout 10m;

    root /var/www/fleet-https;
    index index.html;
    location / {
        try_files $uri $uri/ =404;
    }
}
FLEET_NGINX_SITE
cat > /var/www/fleet-https/index.html <<'FLEET_HTML'
<!doctype html>
<html lang="en"><head><meta charset="utf-8"><title>node2 secure service</title></head>
<body><h1>node2 HTTPS service</h1><p>Protected by Fleet Internal CA.</p></body></html>
FLEET_HTML
chmod 0644 /etc/nginx/nginx.conf /etc/nginx/conf.d/fleet-https.conf /var/www/fleet-https/index.html
restorecon -RF /etc/nginx /var/www/fleet-https
nginx -t

